From ad8a9cfff080d6287f67a7fb715bbcdac1b5b7aa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:30:42 +0100
Subject: [PATCH] faces/choices: add every sensor of a group when picking it

Picking a "[Group]" entry added its sensor id pattern as a single entry,
which has no name, so only an unlabelled chip appeared until the settings
were reopened. Now the matching sensors are added one by one instead.

BUG: 442702
---
 faces/import/Choices.qml | 36 +++++++++++++++++++++++++++++++++++-
 1 file changed, 35 insertions(+), 1 deletion(-)

diff --git a/faces/import/Choices.qml b/faces/import/Choices.qml
index 18988393..9cb1db1a 100644
--- a/faces/import/Choices.qml
+++ b/faces/import/Choices.qml
@@ -414,6 +414,34 @@ Control {

                     property string searchString

+                    // Group entries are patterns, so add the sensors they match instead
+                    function resolveSensorIds(sensorId) {
+                        const isPattern = /[\\*+?(]/
+                        if (!isPattern.test(sensorId)) {
+                            return [sensorId]
+                        }
+                        const expression = new RegExp("^" + sensorId + "$")
+                        const sensors = []
+                        const collect = (parent) => {
+                            for (let row = 0; row < treeModel.rowCount(parent); ++row) {
+                                const index = treeModel.index(row, 0, parent)
+                                const id = treeModel.data(index, Sensors.SensorTreeModel.SensorId)
+                                if (id.length == 0) {
+                                    collect(index)
+                                } else if (!isPattern.test(id) && expression.test(id)) {
+                                    const name = treeModel.data(index, Qt.DisplayRole).replace(/\d+/g, number => number.padStart(10, "0"))
+                                    sensors.push({id, name})
+                                }
+                            }
+                        }
+                        collect(treeModel.index(-1, -1))
+                        if (sensors.length == 0) {
+                            return [sensorId]
+                        }
+                        sensors.sort((a, b) => a.name.localeCompare(b.name))
+                        return sensors.map(sensor => sensor.id)
+                    }
+
                     implicitHeight: contentHeight

                     model: DelegateModel {
@@ -457,7 +485,13 @@ Control {
                                     if (control.selected === undefined || control.selected === null) {
                                         control.selected = []
                                     }
-                                    const length = control.selected.push(model.SensorId)
+                                    let length = control.selected.length
+                                    for (const sensorId of listView.resolveSensorIds(model.SensorId)) {
+                                        if (control.maxAllowedSensors == length) {
+                                            break
+                                        }
+                                        length = control.selected.push(sensorId)
+                                    }
                                     control.selectedChanged()
                                     if (control.maxAllowedSensors == length) {
                                         popup.close();
